import{_ as n,o as r,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Erweiterung des Casts: Kurz, Blümel, Brunner & Sobotka","description":"Wir integrieren die moderne ÖVP-Riege in das Horten-Mysterium. Über Budgetlöcher, Inflation und die Kunst des Schweigens.","frontmatter":{"title":"Erweiterung des Casts: Kurz, Blümel, Brunner & Sobotka","description":"Wir integrieren die moderne ÖVP-Riege in das Horten-Mysterium. Über Budgetlöcher, Inflation und die Kunst des Schweigens.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-moderne-macht-erweiterung.md","filePath":"logbuch/2026-02-27-moderne-macht-erweiterung.md"}'),s={name:"logbuch/2026-02-27-moderne-macht-erweiterung.md"};function a(o,e,d,u,l,m){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="erweiterung-des-casts-kurz-blumel-brunner-sobotka" tabindex="-1">Erweiterung des Casts: Kurz, Blümel, Brunner &amp; Sobotka <a class="header-anchor" href="#erweiterung-des-casts-kurz-blumel-brunner-sobotka" aria-label="Permalink to &quot;Erweiterung des Casts: Kurz, Blümel, Brunner &amp; Sobotka&quot;">​</a></h1><p>Heute haben wir einen weiteren Meilenstein in der Drehbuch-Entwicklung erreicht. Das „Horten-Mysterium“ endet nicht mit dem Ableben von Heidi Horten im Jahr 2022. Die Geschichte des Pointillismus wird durch die moderne ÖVP-Führung fortgeschrieben.</p><p><strong>Die neuen narrativen Schwerpunkte:</strong></p><ul><li><strong>Magnus Brunner &amp; das Budgetloch:</strong> Wir inszenieren das Defizit von 4,7 % als „finanziellen Pointillismus“. Viele kleine Ausgaben ergeben am Ende ein Loch, das keiner gesehen haben will. Die Inflation wird zum Hintergrundrauschen unserer Mockumentary.</li><li><strong>Wolfgang Sobotka:</strong> Er wird zum „Hohenpriester der Geschäftsordnung“. Seine Rolle im Parlament spiegelt die historische Kälte Helmut Hortens wider – nur mit dem Unterschied, dass er heute die Aufarbeitung verwaltet.</li><li><strong>Kurz &amp; Blümel:</strong> Sie sind die digitalen Erben. Ihre Chats sind die modernen „Akten des Schweigens“.</li></ul><p>Diese Figuren ermöglichen es uns, den Bogen von 1936 direkt in die krisengeschüttelte Gegenwart von 2026 zu spannen. Das Projekt gewinnt dadurch an politischer Sprengkraft und aktueller Relevanz.</p><p><em>Dokumentiert von Volti Sodala &amp; Gemini CLI. Februar 2026.</em></p>',6)])])}const h=n(s,[["render",a]]);export{c as __pageData,h as default};
